"""Prepare 1–6 explicit skill references and prompt; no full source scan/QA."""
from pathlib import Path
import json,sys,subprocess
OUT=Path(__file__).resolve().parent;ROOT=OUT.parents[2]
key,start,count=sys.argv[1],int(sys.argv[2]),int(sys.argv[3]);assert 1<=count<=6
catalog=json.loads((ROOT/'references/qqtang-item-data/catalog.json').read_text(encoding='utf-8'));items={e['item_id']:e for e in catalog['items']};ids=list(range(start,start+count))
for ident in ids:assert items[ident]['category']=='skill'
missing=[ident for ident in ids if not(ROOT/f'references/qqtang-item-data/icons/item-{ident}.png').exists()]
if missing:subprocess.run([sys.executable,str(ROOT/'scripts/extract-item-art-reference.py'),*map(str,missing)],cwd=ROOT,check=True)
board=OUT/f'references/structure-{key}.png';subprocess.run([sys.executable,str(ROOT/'scripts/make-item-structure-board.py'),str(board.relative_to(ROOT)),*map(str,ids)],cwd=ROOT,check=True)
themes=[('coin-gain','deep JADEGREEN cover','one small warmGOLD COINSTACK medallion at uppercover; eachcoinhasplainjadecircle, no cashletter','sugar-coin reward gain +6%'),('courage-gain','deep TEALBLUE cover','one small warmGOLD SHIELD enclosing a RED/AMBER courageFLAME at uppercover','courage reward gain +3%'),('score-gain','pale TURQUOISE/JADE cover','one small GOLD FIVEPOINT STAR badge at uppercover','score reward gain +3%'),('reputation-gain','warm IVORY/SAGEGREEN cover','one small JADE LAUREL/crest goldrimmedSEAL at uppercover','reputation reward gain +3%'),('materials-double','soft LAVENDER/JADE cover','small pair of JADE CRYSTALS withtinygoldherbleaf at uppercover','chance for double materials +3%'),('score-double','deep EMERALD cover','exactly TWO small GOLD FIVEPOINT STARS at uppercover','chance for double score +3%'),('courage-double','warm muted CRIMSON/JADE cover','exactly TWO small golden SHIELD/FLAME badges at uppercover','chance for double courage +3%'),('affinity-double','soft PEACHPINK/IVORY cover','TWO small linked JADE HEART pendants at uppercover','chance for double pet affinity +3%')]
positions=['TOPLEFT','TOPMIDDLE','TOPRIGHT','BOTTOMLEFT','BOTTOMMIDDLE','BOTTOMRIGHT'];entries=[]
prompt=['Create originalfineHDHANDPAINTED DAOISTQ static PETSKILLBOOK inventoryicons, transparent1536x1024,3columns2rows of512squarecells. Image1 supplies ONLYsourcefunctionalbookshape andorder/level; nevercopyitsredpixelart/LEVELlettering. Image2/3 PRIMARYSTYLE jade/teal/ivorywarmgold,roundedfinecloudedges,cleanmattecloth/paper/jadehandpainting. Image4ouralreadydrawnitemfinish, sameworldfidelity. Each icon is ONECLOSEDuprightBOOK, nearfrontalview withsmallright/bottomivorypageblock, softsquarecorners, thinfinewarmgoldcoverrim, slimribbonbookmarkatbottom. No externaliconframe, smoke/glow/scenery/ground, detachedparticles,labels orwatermark. Keepatleast50pxalphaemptyguttersaroundeach512cell, allcorners/page/ribbonfullyinside. Make largerArabicLEVELNUMERAL sharp andcorrect at centrecover on subtleplainivorylabel; NO wordLEVEL, no otherletters,percentagesor text. Small functionalemblem atuppercover mustnotcover numeral. Differentthemesaretintedcovers/emblems, not newgameabilities. Thesearestaticicons,not animation.']
for n,ident in enumerate(ids):
    e=items[ident];group=(ident-27001)//10;level=(ident-27001)%10+1;slug,color,symbol,effect=themes[group];name=f'{slug}-level-{level}'
    prompt.append(f'{positions[n]} item{ident}, source name {e["name"]}, level{level}, function:{effect}. Paint {color}, {symbol}. Large central Arabic numeral MUST be exactly "{level}". Sameclosedbook/readablelevelshape as source; fineivorypages, gold/jadebookclaspinsideoutline. Do notpaintfunctiontext. Makelevelnumberbig enoughreadableat64px.')
    entries.append({'itemId':ident,'name':name,'rect':[n%3*512,n//3*512,(n%3+1)*512,(n//3+1)*512]})
if len(ids)<6:prompt.append('UNUSEDcellsafterlistedonescompletelytransparentempty. Noextraicons.')
(OUT/f'prompts/batch-{key}.prompt.txt').write_text('\n'.join(prompt)+'\n',encoding='utf-8')
(OUT/f'exports/batch-{key}.json').write_text(json.dumps({'assetDirectory':'assets/items/skills','source':f'assets/items/skills/skills-{key}-v1.png','items':entries},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(OUT/f'exports/batch-{key}.requirements.json').write_text(json.dumps({'sourceCatalog':'references/qqtang-item-data/catalog.json','items':[items[i]for i in ids],'scope':'independent static skill inventory icons only; not effects or animation'},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'batch':key,'ids':ids,'scope':'static icons'}))
